sql_query:
SELECT "Treatment regimen"
FROM clinical_trials
WHERE LOWER(TRIM(COALESCE("Treatment regimen", ''))) NOT IN ('', 'none', 'null', 'nan') AND TRIM(COALESCE("Cancer type", '')) = 'Non-Small Cell Lung' AND TRIM(COALESCE("Included in MA", '')) = 'No' AND TRIM(COALESCE("Type of combination", '')) = 'ICI+TKI';

ground_truth_sql:
WITH base AS (
SELECT "NCT", "PubMed ID", "Trial name", "Treatment regimen" AS source_value FROM clinical_trials WHERE LOWER(TRIM(COALESCE("Treatment regimen", ''))) NOT IN ('', 'none', 'null', 'nan') AND TRIM(COALESCE("Cancer type", '')) = 'Non-Small Cell Lung' AND TRIM(COALESCE("Included in MA", '')) = 'No' AND TRIM(COALESCE("Type of combination", '')) = 'ICI+TKI'
)
SELECT "NCT", "PubMed ID", "Trial name", source_value, derive_tki_agents(source_value) AS "tki_agents"
FROM base;
